{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "Under MESA, repeated testing and evidence of stability are separate issues. Neither is established by one reported run when repetition is unspecified.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing information does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not show variation across repeated runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "MESA distinguishes an explicit absence of repeated testing from missing information. The passage rules out repeated testing but does not establish either stability or instability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "A single run supplies no evidence of score stability across repetitions."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "MESA supports both the occurrence of repeated testing and observed stability here. The reported range meets the stated criterion for this system and these conditions.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly reports repetitions under unchanged conditions and their score range."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range meets the report's stability criterion for this comparison."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "Under MESA, testing occurred even though its findings were unfavourable. The observed variation exceeds the report's stability criterion.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under unchanged conditions measured score changes."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range explicitly exceeds the defined stability limit."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "MESA treats installation documentation as information about access and reproducibility, not evidence of repeated testing or stability. Both remain unresolved.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not resolve whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The installation update supplies no evidence about score variation across runs."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "MESA supports the reported comparison on the evaluated grid puzzles. The narrow intended use fits that evidence; a claim about general intelligence would exceed it.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative ability across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "MESA identifies a mismatch between the broad intended use and the narrow evidence. The grid-puzzle comparison is supported, but selecting for general intelligence is not justified by these findings.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broader intended use supplies no additional evidence of general intelligence across domains."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "MESA distinguishes initial test scores from later evidence about practical use. The randomized trial supports better correctness with A in the studied workshop, while safety and time remain unmeasured.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated link between test scores and real workshop decision improvements."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial and reported interval support better correctness with A for the studied workshop and conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Better decision correctness does not by itself establish improved workplace safety."
        }
      ]
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was treated as insufficient information, not as proof that a condition failed."
}
